// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type EyeTypingRevealProps = Record<string, any>;

const EyeTypingReveal: React.FC<EyeTypingRevealProps> = ({
  backgroundColor = "#f1f5f9",
  transparentBackground = false,
  enableTexture = true,
  textureOpacity = 0.08,
  durationInSeconds = 8,
  typedText = "You might want to keep an eye on this.",
  finalText = "Tuesday March 11th",
  textColor = "#0f172a",
  eyeColor = "#334155",
  typingSpeed = 2,
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Space Grotesk"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Parse background
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timings
  const startFrame = 20; // Slight delay before typing starts
  const totalChars = Math.max(1, typedText.length);
  const typingDuration = totalChars * typingSpeed;
  const endTypingFrame = startFrame + typingDuration;
  const revealStartFrame = endTypingFrame + 30; // 1 second pause after typing

  // Typing Logic
  const charsToReveal = Math.floor(Math.max(0, frame - startFrame) / typingSpeed);
  const currentTypedText = typedText.substring(0, charsToReveal);
  
  const showCursor = frame < revealStartFrame;
  const cursorOpacity = Math.floor(frame / 15) % 2 === 0 ? 1 : 0;

  // Face/Eye Animation Logic
  const faceScaleIn = spring({
    fps,
    frame: frame - 5,
    config: { damping: 12, mass: 0.6 },
  });

  const blinkPhase = frame % 150;
  const blinkScale = interpolate(
    blinkPhase,
    [0, 140, 143, 146, 150],
    [1, 1, 0.05, 1, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  // Pupil tracks typing progress from left to right, then returns to center
  const typingProgress = Math.min(1, Math.max(0, (frame - startFrame) / typingDuration));
  let pupilX = interpolate(typingProgress, [0, 1], [-16, 16], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  
  if (frame > endTypingFrame + 15) {
    pupilX = interpolate(
      frame,
      [endTypingFrame + 15, endTypingFrame + 30],
      [16, 0],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );
  }

  // Text 2 Transition In
  const text2Opacity = interpolate(
    frame,
    [revealStartFrame + 10, revealStartFrame + 25],
    [0, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );
  const text2Scale = spring({
    fps,
    frame: frame - (revealStartFrame + 10),
    config: { damping: 14, mass: 0.8 },
  });
  const text2Y = interpolate(
    frame,
    [revealStartFrame + 10, revealStartFrame + 25],
    [30, 0],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  const eyeSvg = (
    <svg
      viewBox="0 0 100 100"
      width={width * 0.12}
      height={width * 0.12}
      style={{ overflow: "visible", transition: "none" }}
    >
      <g
        transform={`scale(1, ${blinkScale})`}
        style={{ transformOrigin: "50px 50px", transition: "none" }}
      >
        {/* Sclera (Outer Eye) - Perfectly round for squishy look */}
        <circle
          cx="50"
          cy="50"
          r="46"
          fill="#ffffff"
          style={{ transition: "none" }}
        />
        {/* Soft inner shadow/border to define the 3D globe */}
        <circle
          cx="50"
          cy="50"
          r="46"
          fill="transparent"
          stroke="rgba(0,0,0,0.08)"
          strokeWidth="4"
          style={{ transition: "none" }}
        />
        
        {/* Pupil - Large and dark */}
        <circle
          cx={50 + pupilX}
          cy={50}
          r="28"
          fill={eyeColor}
          style={{ transition: "none" }}
        />
        
        {/* Squishy highlight hook overlapping pupil (simulates sclera fold) */}
        <path
          d={`M ${30 + pupilX} 28 Q ${46 + pupilX} 24 ${46 + pupilX} 44`}
          fill="none"
          stroke="#ffffff"
          strokeWidth="14"
          strokeLinecap="round"
          style={{ transition: "none" }}
        />

        {/* Small secondary wet highlight */}
        <circle
          cx={50 + pupilX + 10}
          cy={62}
          r="4"
          fill="#ffffff"
          style={{ transition: "none", opacity: 0.9 }}
        />
      </g>
    </svg>
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Space Grotesk",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        transition: "none",
      }}
    >
      {/* Texture Overlay */}
      {enableTexture && !transparentBackground && (
        <AbsoluteFill
          style={{
            opacity: textureOpacity,
            pointerEvents: "none",
            transition: "none",
            zIndex: 0,
          }}
        >
          <svg width="100%" height="100%" style={{ transition: "none" }}>
            <filter id="noiseFilter">
              <feTurbulence
                type="fractalNoise"
                baseFrequency="0.65"
                numOctaves="3"
                stitchTiles="stitch"
              />
              <feColorMatrix type="saturate" values="0" />
            </filter>
            <rect width="100%" height="100%" filter="url(#noiseFilter)" style={{ transition: "none" }} />
          </svg>
        </AbsoluteFill>
      )}

      {/* Typed Text Container (Top) */}
      <div
        style={{
          height: 120,
          display: "flex",
          alignItems: "flex-end",
          justifyContent: "center",
          width: "80%",
          textAlign: "center",
          marginBottom: 40,
          transition: "none",
          zIndex: 1,
        }}
      >
        <div
          style={{
            fontSize: 64,
            fontWeight: 400,
            color: textColor,
            transition: "none",
          }}
        >
          {currentTypedText}
          {showCursor && (
            <span
              style={{
                opacity: cursorOpacity,
                color: eyeColor,
                marginLeft: 4,
                transition: "none",
              }}
            >
              |
            </span>
          )}
        </div>
      </div>

      {/* Squishy Face Container (Middle) */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          transform: `scale(${faceScaleIn})`,
          transition: "none",
          marginBottom: 40,
          zIndex: 1,
        }}
      >
        {/* Eyes Row */}
        <div 
          style={{ 
            display: "flex", 
            flexDirection: "row", 
            gap: 10, 
            transition: "none", 
            zIndex: 2 
          }}
        >
          {eyeSvg}
          {eyeSvg}
        </div>
      </div>

      {/* Final Reveal Text Container (Bottom) */}
      <div
        style={{
          height: 120,
          width: "80%",
          textAlign: "center",
          display: "flex",
          justifyContent: "center",
          alignItems: "flex-start",
          transition: "none",
          zIndex: 1,
        }}
      >
        <div
          style={{
            fontSize: 96,
            fontWeight: 700,
            color: eyeColor,
            opacity: text2Opacity,
            transform: `translateY(${text2Y}px) scale(${text2Scale})`,
            transition: "none",
          }}
        >
          {finalText}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default EyeTypingReveal;